-- Fictional records only; the same assertions can run against production in ROLLBACK.
do $tests$
declare c uuid:=gen_random_uuid();other_c uuid:=gen_random_uuid();adm uuid:=gen_random_uuid();player uuid:=gen_random_uuid();manager uuid:=gen_random_uuid();coach uuid:=gen_random_uuid();
 mid uuid:=gen_random_uuid();ours uuid:=gen_random_uuid();theirs uuid:=gen_random_uuid();batter uuid:=gen_random_uuid();bowler uuid:=gen_random_uuid();inning uuid:=gen_random_uuid();other_inning uuid:=gen_random_uuid();
 fid uuid:=gen_random_uuid();today date:=(now() at time zone 'Australia/Sydney')::date;card jsonb;sid uuid;result jsonb;aid uuid;message uuid;rejected boolean;n integer;before_threads integer;
 edition_id uuid:=gen_random_uuid();request_data jsonb;award_candidate jsonb;old_match uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email,email_confirmed_at) values(adm,'milestone-admin@example.invalid',now()),(player,'milestone-player@example.invalid',now()),(manager,'milestone-manager@example.invalid',now()),(coach,'milestone-coach@example.invalid',now());
 insert into public.clubs(id,name,slug,created_by) values(c,'Fictional Achievement Club','qa-'||c,adm),(other_c,'Fictional Other Club','qa-'||other_c,adm);
 insert into public.club_memberships(club_id,user_id,role,permission_role) values(c,adm,'admin','admin'),(c,player,'player','none'),(c,manager,'player','none'),(c,coach,'coach','coach');
 insert into club_selection_private.access(club_id,status,mode,timezone) values(c,'pilot','bundle','Australia/Sydney');
 insert into club_selection_private.social_managers values(c,manager);
 assert mirelion_assist_private.club_staff(c,adm),'Admin is staff';
 assert mirelion_assist_private.club_staff(c,coach),'Coach is staff';
 assert mirelion_assist_private.club_staff(c,manager),'Playing Socials Manager is staff';
 assert not mirelion_assist_private.club_staff(c,player),'Ordinary player is not staff';
 assert not mirelion_assist_private.club_staff(other_c,manager),'Staff grants are club-scoped';
 perform set_config('request.jwt.claim.sub',player::text,true);
 assert public.club_selections_api(c,'access')->>'assist_staff'='false','Existing access RPC gates player download';
 select count(*) into before_threads from mirelion_assist_private.threads;
 rejected:=false;begin perform public.mirelion_assist('create',jsonb_build_object('club_id',c,'request_id',gen_random_uuid(),'subject','Not allowed','body','Fictional test','category','help'));exception when insufficient_privilege then rejected:=true;end;
 assert rejected and (select count(*) from mirelion_assist_private.threads)=before_threads,'Player cannot open Assist via direct/stale RPC';
 perform set_config('request.jwt.claim.sub',manager::text,true);
 assert public.club_selections_api(c,'access')->>'assist_staff'='true','Socials staff download is allowed';
 result:=public.mirelion_assist('create',jsonb_build_object('club_id',c,'request_id',gen_random_uuid(),'subject','Fictional staff support','body','Fictional test','category','help'));
 assert result->>'thread_id' is not null,'Staff can still use private support';
 delete from club_selection_private.social_managers where club_id=c and user_id=manager;
 rejected:=false;begin perform public.mirelion_assist('thread',jsonb_build_object('club_id',c,'thread_id',result->>'thread_id'));exception when insufficient_privilege then rejected:=true;end;
 assert rejected,'Removing staff access invalidates old thread links';
 insert into club_selection_private.social_managers values(c,manager);
 card:=jsonb_build_object('schema_version',2,'provider','playhq_au','match_id',mid,'status','in_progress','format_key','limited_overs','grade','Fictional 1st Grade','dates',jsonb_build_array(today),
  'teams',jsonb_build_array(jsonb_build_object('id',ours,'name','Our team'),jsonb_build_object('id',theirs,'name','Visitors')),
  'innings',jsonb_build_array(jsonb_build_object('id',inning,'number',1,'team_id',ours,'complete',false,'batters',jsonb_build_array(jsonb_build_object('player_id',batter,'name','Fictional Batter','status','played','runs',100,'not_out',true,'importable',false,'figures_valid',true))),
   jsonb_build_object('id',other_inning,'number',1,'team_id',theirs,'complete',false,'bowlers',jsonb_build_array(jsonb_build_object('player_id',bowler,'name','Fictional Bowler','team_id',ours,'wickets',5,'runs',20,'importable',false)))));
 result:=club_selection_private.social_milestone_candidates(jsonb_build_array(jsonb_build_object('scorecard',card,'our_team',ours)));
 assert jsonb_array_length(result)=2,'100 runs and five wickets qualify during play';
 assert not exists(select 1 from jsonb_array_elements(result) p where p->>'kind'='results'),'No result is inferred from a live achievement';
 assert jsonb_array_length(club_selection_private.social_milestone_candidates(jsonb_build_array(jsonb_build_object('scorecard',jsonb_set(card,'{innings}',(card->'innings')||jsonb_build_array(jsonb_set(card#>'{innings,0}','{id}',to_jsonb(gen_random_uuid())))),'our_team',ours))))=3,'Separate innings remain separate achievements';
 assert club_selection_private.social_milestone_candidates(jsonb_build_array(jsonb_build_object('scorecard',card,'our_team',theirs)))='[]','Opponent performances do not trigger club awards';
 assert club_selection_private.social_milestone_candidates(jsonb_build_array(jsonb_build_object('scorecard',jsonb_set(jsonb_set(card,'{innings,0,batters,0,runs}','99'),'{innings,1,bowlers,0,wickets}','4'),'our_team',ours)))='[]','99 and four wickets do not qualify';
 insert into club_selection_private.team_week_sources(club_id,source_match_id,team_id,updated_by) values(c,mid,ours,adm);
 insert into public.match_review_scorecards(club_id,source_match_id,fetched_by,scorecard) values(c,mid,adm,card) returning id into sid;
 perform club_selection_private.collect_social_milestones(c,mid);
 assert not exists(select 1 from club_selection_private.social_milestone_alerts where club_id=c),'Alerts default off';
 result:=club_selection_private.social_awards_api(c,'save_settings',jsonb_build_object('revision',0,'enabled',jsonb_build_array('team_week'),'milestone_alerts',true));
 assert result->>'milestone_alerts'='true' and (result->'enabled') ?& array['century','five_wickets'],'Opt-in enables both creation routes';
 assert club_selection_private.social_awards_api(c,'save_settings',jsonb_build_object('revision',0,'enabled',jsonb_build_array('team_week'),'milestone_alerts',true))=result,'Lost save response retries without another revision';
 insert into public.match_review_scorecards(club_id,source_match_id,fetched_by,scorecard) values(c,mid,adm,card);
 set constraints all immediate;
 assert (select count(*) from club_selection_private.social_milestone_alerts where club_id=c)=2,'One alert for each separate achievement';
 assert (select count(*) from club_batting_private.club_message_recipients r join club_selection_private.social_milestone_alerts a on a.message_id=r.message_id where a.club_id=c and r.user_id=manager)=2,'Both alerts go to the Socials Manager';
 assert not exists(select 1 from club_batting_private.club_message_recipients r join club_selection_private.social_milestone_alerts a on a.message_id=r.message_id where a.club_id=c and r.user_id in(player,coach,adm)),'Ordinary players, coaches and covered admins are not notified';
 select id,message_id into aid,message from club_selection_private.social_milestone_alerts where club_id=c and kind='century';
 result:=club_selection_private.social_milestone_context(c,jsonb_build_object('milestone_id',aid));
 assert result->>'kind'='century' and result#>>'{candidate,name}'='Fictional Batter','Alert resolves to exact post and player';
 award_candidate:=result->'candidate';
 request_data:=jsonb_build_object('id',edition_id,'milestone_id',aid,'kind','century','week_end',result->>'week_end','award_scope',result->'award_scope','label','Fictional century','sources',jsonb_build_array(award_candidate),'sha256',repeat('a',64),'bytes',100);
 result:=club_selection_private.social_awards_api(c,'context',request_data);
 assert exists(select 1 from jsonb_array_elements(result->'candidates') x where x->>'key'=award_candidate->>'key'),'Live alert reaches the real award editor';
 result:=club_selection_private.social_awards_api(c,'reserve_image',request_data);
 insert into storage.objects(bucket_id,name,metadata) values('club-social-awards',result->>'path','{"size":100}');
 result:=club_selection_private.social_awards_api(c,'finish_image',jsonb_build_object('id',edition_id));
 assert result->>'saved'='true' and club_selection_private.social_award_scores_current(c,edition_id),'Live achievement image can finish and pass posting freshness checks';
 rejected:=false;begin perform club_selection_private.social_milestone_context(other_c,jsonb_build_object('milestone_id',aid));exception when insufficient_privilege then rejected:=true;end;
 assert rejected,'Alert cannot cross club boundaries';
 assert club_batting_private.message_recipient_allowed(message,manager),'Assigned manager can receive alert';
 assert not club_batting_private.message_recipient_allowed(message,player),'Player cannot read another recipient alert';
 insert into public.match_review_scorecards(club_id,source_match_id,fetched_by,scorecard) values(c,mid,adm,jsonb_set(card,'{innings,0,batters,0,runs}','120'));
 assert not club_selection_private.social_award_scores_current(c,edition_id),'Saved images must be reviewed when their scores change';
 assert (select count(*) from club_selection_private.social_milestone_alerts where club_id=c)=2,'Repeat import and higher score do not send another alert';
 insert into public.match_review_scorecards(club_id,source_match_id,fetched_by,scorecard) values(c,mid,adm,jsonb_set(card,'{innings,0,batters,0,runs}','99'));
 assert not club_selection_private.social_milestone_message_allowed(message,manager),'Corrected-away achievement cancels pending delivery';
 rejected:=false;begin perform club_selection_private.social_milestone_context(c,jsonb_build_object('milestone_id',aid));exception when raise_exception then rejected:=true;end;
 assert rejected,'Corrected score cannot create an invalid award';
 insert into public.match_review_scorecards(club_id,source_match_id,fetched_by,scorecard) values(c,mid,adm,card);
 assert (select count(*) from club_selection_private.social_milestone_alerts where club_id=c)=2,'Correction back does not duplicate notification';
 insert into club_selection_private.team_week_sources(club_id,source_match_id,team_id,updated_by) values(c,old_match,ours,adm);
 insert into public.match_review_scorecards(club_id,source_match_id,fetched_by,scorecard) values(c,old_match,adm,jsonb_set(jsonb_set(card,'{match_id}',to_jsonb(old_match)),'{dates}',jsonb_build_array(today-30)));
 assert not exists(select 1 from club_selection_private.social_milestone_alerts where club_id=c and source_match_id=old_match),'Historical imports do not backfill alerts';
 delete from club_selection_private.social_managers where club_id=c and user_id=manager;
 assert not club_selection_private.social_milestone_message_allowed(message,manager),'Revoked manager loses queued alert access';
 insert into club_selection_private.social_managers values(c,manager);
 insert into club_selection_private.fixtures(id,club_id,details,updated_by) values(fid,c,jsonb_build_object('format','t20','days',jsonb_build_array(jsonb_build_object('date',today,'start','10:00'))),adm);
 assert club_selection_private.playhq_results_due(fid,null,(today+time '10:00') at time zone 'Australia/Sydney')=(today+time '10:30') at time zone 'Australia/Sydney','Opt-in starts checks during play';
 assert club_selection_private.playhq_results_due(fid,(today+time '11:00') at time zone 'Australia/Sydney',(today+time '11:00') at time zone 'Australia/Sydney')=(today+time '11:10') at time zone 'Australia/Sydney','Checks repeat every ten minutes during play';
 result:=club_selection_private.social_awards_api(c,'save_settings',jsonb_build_object('revision',1,'enabled',jsonb_build_array('century','five_wickets'),'milestone_alerts',false));
 assert not club_selection_private.social_milestone_message_allowed(message,manager),'Opt-out cancels pending delivery';
 assert club_selection_private.playhq_results_due(fid,null,(today+time '10:00') at time zone 'Australia/Sydney')=(today+time '13:30') at time zone 'Australia/Sydney','Opt-out retains expected-finish scheduling';
 assert not has_function_privilege('authenticated','club_selection_private.collect_social_milestones(uuid,uuid)','EXECUTE'),'Collection helper remains private';
 assert not has_table_privilege('authenticated','club_selection_private.social_milestone_alerts','SELECT'),'Alert ledger is not exposed';
end $tests$;
